const grid=document.querySelector('#grid'), search=document.querySelector('#search'), dep=document.querySelector('#department'), rar=document.querySelector('#rarity');
const drawer=document.querySelector('#drawer'), detail=document.querySelector('#detail');
[...new Set(cards.map(x=>x.department))].sort().forEach(x=>dep.insertAdjacentHTML('beforeend',`<option>${x}</option>`));
[...new Set(cards.map(x=>x.rarity))].sort().forEach(x=>rar.insertAdjacentHTML('beforeend',`<option>${x}</option>`));
function render(){
 const q=search.value.toLowerCase(); const rows=cards.filter(c=>(!dep.value||c.department===dep.value)&&(!rar.value||c.rarity===rar.value)&&JSON.stringify(c).toLowerCase().includes(q));
 grid.innerHTML=rows.map(c=>`<article class="card" data-id="${c.number}"><div class="screen">
 <img class="art" src="${c.image}" alt="${c.name}"/>
 <div class="hud"><div class="topline"><span>${c.card_id}</span><span>LV.${c.level}</span></div><h2>${c.name}</h2><p class="role">${c.role}</p>
 <div class="chips"><span class="chip">${c.department}</span><span class="chip">${c.rarity}</span><span class="chip">${c.record_kind}</span></div>
 <div class="command">${c.command}</div><div class="stats"><span>PWR ${c.power}</span><span>PRE ${c.precision}</span><span>SPD ${c.speed}</span><span>RES ${c.resilience}</span><span>INT ${c.intelligence}</span><span>TEAM ${c.teamwork}</span></div></div></div></article>`).join('');
 document.querySelectorAll('.card').forEach(el=>el.onclick=()=>openCard(cards.find(c=>c.number===+el.dataset.id)));
}
async function openCard(c){
 const m=await fetch(c.metadata).then(r=>r.json());
 detail.innerHTML=`<div class="detail"><div><img src="${m.image}" alt=""><div class="panel"><b>Media Slots</b><p>Animation · Video · GLB 3D · Audio · AR/USDZ</p></div></div>
 <div><p class="eyebrow">${m.spatial_screen.card_id} // LEVEL ${m.spatial_screen.level}</p><h2>${m.identity.name||m.name}</h2><p>${m.description}</p>
 <div class="panel"><b>Command</b><pre>${m.command.primary}</pre><pre>${m.command.verify}</pre><pre>${m.command.handoff}</pre></div>
 <div class="panel"><b>Workflow</b><p>${m.workflow.summary}</p><p><strong>Inputs:</strong> ${m.workflow.inputs.join(' · ')}</p><p><strong>Outputs:</strong> ${m.workflow.outputs.join(' · ')}</p><p><strong>Proof Gate:</strong> ${m.workflow.proof_gate}</p><p><strong>Handoffs:</strong> ${m.workflow.synced_agents.join(' → ')}</p></div>
 <div class="panel"><b>Abilities</b>${m.abilities.map(a=>`<p><strong>${a.name}</strong> — ${a.effect}</p>`).join('')}</div>
 ${Object.entries(m.stats).map(([k,v])=>`<label>${k} ${v}<div class="bar"><i style="width:${v}%"></i></div></label>`).join('')}
 <div class="panel"><b>License</b><p>${m.license.artwork}</p><p>${m.license.disclaimer}</p></div></div></div>`;
 drawer.showModal();
}
search.oninput=render;dep.onchange=render;rar.onchange=render;document.querySelector('#close').onclick=()=>drawer.close();render();
